const fs = require('fs');
const path = require('path');

let item;
try { 
  item = $input.first().json; 
} catch(e) { 
  throw new Error('No se pudo acceder a datos de entrada.'); 
}

if (!item) {
  throw new Error('El objeto json recibido está vacío.');
}

let rawItem = Array.isArray(item) ? item[0] : item;
if (typeof rawItem === 'string') rawItem = JSON.parse(rawItem);

if (rawItem.parameter && Array.isArray(rawItem.parameter)) {
    rawItem.parameter.forEach(p => {
        if (p.name && p.value !== undefined) {
            rawItem[p.name] = p.value;
        }
    });
}

if (rawItem.json && typeof rawItem.json === 'object') {
    Object.assign(rawItem, rawItem.json);
}

const productId = rawItem.productId || rawItem.NOMBRE || 'PRODUCTO_DESCONOCIDO';
const categoryRaw = rawItem.categoryRaw || rawItem.CATEGORIA || 'General';
const marca = rawItem.marca || 'yourbrand';
const fileName = rawItem.fileName || (rawItem.path ? path.basename(rawItem.path) : 'imagen.jpg');

// CAMBIO CRÍTICO: RUTA A LOGO.PNG
const logoPath = rawItem.logoPath || '/data/logo.png';
const productoPath = rawItem.productoPath || rawItem.path;

if (!productoPath) {
    throw new Error('ERROR: No se recibió la ruta del producto.');
}

try {
  const logoBuffer = fs.readFileSync(logoPath);
  const productoBuffer = fs.readFileSync(productoPath);

  const getMime = (p) => {
    const ext = path.extname(p).toLowerCase();
    if (ext === '.png') return 'image/png';
    if (ext === '.webp') return 'image/webp';
    return 'image/jpeg';
  };

  return [{
    json: {
      ...rawItem,
      productId,
      categoryRaw,
      marca,
      fileName,
      logoPath,
      productoPath,
      logoMime: getMime(logoPath),
      productoMime: getMime(productoPath),
      logoBase64: logoBuffer.toString('base64'),
      productoBase64: productoBuffer.toString('base64')
    },
    binary: {
      "dataProducto": {
        data: productoBuffer.toString('base64'),
        mimeType: getMime(productoPath),
        fileName: fileName
      }
    }
  }];
} catch (e) {
  throw new Error('Fallo al leer archivos físicos: ' + e.message);
}

