const path = require('path');
const fs = require('fs');

const binaryData = $input.first().binary;
const currentItem = $('Read Files & Base64').item.json;

// IMPORTANTE: productId viene limpio desde el origen
const marca = currentItem.marca || 'yourbrand';
const categoria = currentItem.categoryRaw || 'General';
const nombreProducto = currentItem.productId || 'producto';

// El flag de IA se usa SOLO para el nombre del archivo
// En esta versión simplificada iaUsed es false por defecto, 
// pero mantenemos la lógica por si quieres reactivarla.
const iaUsed = currentItem.iaUsed || false;
const sufijoIA = iaUsed ? ' IA' : '';

// Estandarización de la ruta final con sufijo IA SOLO en el archivo
const extension = '.jpg';
const destinoPath = `/data/fotosProcesadas/${marca}/${categoria}/${nombreProducto}${sufijoIA}${extension}`;

try {
  const targetDir = path.dirname(destinoPath);
  if (!fs.existsSync(targetDir)) {
    fs.mkdirSync(targetDir, { recursive: true });
  }
} catch (e) {
  console.error('Error creando directorio:', e.message);
}

return [{
  json: {
    ...currentItem,
    destinoPath
  },
  binary: binaryData
}];

